export const replyToEmail = defineFunction({
  name: "emailbison.reply_to_email",
  connector: "emailbison",
  class: "sensitive",
  act: true,
  description: "Answer a reply (reply_id): the email leaves at once. Either reply_all true (the right sending account and the original recipients), or sender_email_id and to_emails [{email_address, name}]. message is the body, content_type html or text; cc_emails and bcc_emails add recipients; inject_previous_email_body quotes the email answered. Read get_reply_thread first. Answers the sent reply.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "required": ["reply_id", "message"],
    "if": {"properties": {"reply_all": {"const": true}}, "required": ["reply_all"]},
    "then": true,
    "else": {"required": ["sender_email_id", "to_emails"]},
    "properties": {
      "reply_id": {"type": "integer", "minimum": 1},
      "message": {"type": "string", "minLength": 1, "personal": true},
      "content_type": {"type": "string", "enum": ["html", "text"]},
      "reply_all": {"type": "boolean"},
      "sender_email_id": {"type": "integer", "minimum": 1},
      "to_emails": {
        "type": "array",
        "minItems": 1,
        "maxItems": 50,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": ["email_address"],
          "properties": {
            "email_address": {"type": "string", "pattern": "^\\S+@\\S+$", "personal": true},
            "name": {"type": ["string", "null"], "personal": true}
          }
        }
      },
      "cc_emails": {
        "type": "array",
        "minItems": 1,
        "maxItems": 50,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": ["email_address"],
          "properties": {
            "email_address": {"type": "string", "pattern": "^\\S+@\\S+$", "personal": true},
            "name": {"type": ["string", "null"], "personal": true}
          }
        }
      },
      "bcc_emails": {
        "type": "array",
        "minItems": 1,
        "maxItems": 50,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": ["email_address"],
          "properties": {
            "email_address": {"type": "string", "pattern": "^\\S+@\\S+$", "personal": true},
            "name": {"type": ["string", "null"], "personal": true}
          }
        }
      },
      "inject_previous_email_body": {"type": "boolean"}
    }
  },
  examples: [
    { title: "Reply to all", input: {"reply_id": 239, "reply_all": true, "message": "Thanks, Tuesday 10am works for me.", "content_type": "text"} },
    { title: "Reply from one account", input: {"reply_id": 239, "sender_email_id": 25057, "to_emails": [{"email_address": "jane.doe@example.com", "name": "Jane Doe"}], "message": "Hi Jane, here is the link.", "content_type": "text"} },
  ],
  refusals: [
    { code: "reply_not_found", when: 404, message: "No reply with this id in this EmailBison workspace." },
  ],
  request: {
    method: "POST",
    path: "/replies/{reply_id}/reply",
    pathParams: ["reply_id"],
    query: {},
    body: {"message": "message", "content_type": "content_type", "reply_all": "reply_all", "sender_email_id": "sender_email_id", "to_emails": "to_emails", "cc_emails": "cc_emails", "bcc_emails": "bcc_emails", "inject_previous_email_body": "inject_previous_email_body"},
    headers: {},
  },
  output: { strip: ["data.reply.raw_body", "data.reply.headers", "data.reply.attachments.download_url"] },
  confirm: { summary: "Send this reply to EmailBison reply {reply_id} now: the email leaves at once." },
})

